UPDATE public.places SET short_description='Neolitik dönemde yerleşim görmüş, UNESCO Dünya Mirası Listesi’nde yer alan arkeolojik alan.', long_description='Çatalhöyük, insanlık tarihinin erken yerleşim düzeni ve toplumsal yaşamı hakkında önemli bilgiler sunan Neolitik dönem arkeolojik alanıdır.', source_url='https://whc.unesco.org/en/list/1405/', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Konya' AND slug='konya-catalhoyuk-neolitik-kenti';
INSERT INTO public.places (name,category,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,external_id,verified,trust_score,is_active,content_review_status,tags,updated_at)
SELECT s.name,s.category,s.city,s.address,s.latitude,s.longitude,s.slug,s.short_description,s.long_description,s.source_url,'curated_seed',s.slug,true,95,true,'source_backed',jsonb_build_array(s.category,s.city),now()
FROM (VALUES
('Mevlana Müzesi','Müze ve kültür','Konya','Aziziye Mahallesi, Karatay',37.871,32.505,'konya-mevlana-muzesi','Mevlana Celaleddin Rumi’nin türbesini ve Mevlevilik mirasını barındıran Konya’nın simge kültür noktası.','Mevlana Müzesi, Mevlana Celaleddin Rumi’nin türbesi çevresinde oluşan tarihî külliyede yer alır ve Mevlevilik kültürünü tanıtan başlıca ziyaret noktalarındandır.','https://muze.gov.tr/muze-detay?DistId=MRK&SectionId=KMM01'),
('Arslantepe Höyüğü','Tarih ve arkeoloji','Malatya','Orduzu, Battalgazi',38.3821,38.3612,'malatya-arslantepe-hoyugu','UNESCO Dünya Mirası alanı; erken devlet yapısı ve anıtsal yapılarıyla bilinen çok katmanlı arkeolojik höyük.','Arslantepe Höyüğü, MÖ 5. binyıldan sonraki dönemlere uzanan yerleşim katmanlarıyla Anadolu’nun önemli arkeolojik alanlarındandır. Kültür ve Turizm Bakanlığının duyurusunda 1 Eylül 2025 itibarıyla geçici ziyaret kapanışı belirtilmiştir; gitmeden önce güncel durumu kontrol edin.','https://malatya.ktb.gov.tr/TR-58312/arslantepe.html'),
('Deyrulzafaran Manastırı','Tarih ve mimari','Mardin','Mardin’in doğusu',37.309,40.735,'mardin-deyrulzafaran-manastiri','Mardin Ovası’na hâkim konumdaki, Süryani Ortodoks geleneğinin önemli tarihî manastırı.','Deyrulzafaran Manastırı, farklı dönemlerde eklenen yapılarıyla yüzyıllar içinde gelişmiş ve Süryani cemaatinin önemli dinî merkezlerinden biri olmuştur. Ziyaretler rehberli düzenle yapılabildiğinden güncel saatler kontrol edilmelidir.','https://mardin.ktb.gov.tr/TR-373254/deyrulzafaran-manastiri.html'),
('Dara Antik Kenti','Tarih ve arkeoloji','Mardin','Oğuz köyü, Artuklu',37.177,40.954,'mardin-dara-antik-kenti','Geç Antik Çağ’da önemli bir askerî ve yerleşim merkezi olan arkeolojik alan.','Dara Antik Kenti, Mardin’in güneydoğusunda yer alan; kaya mezarları, su yapıları ve yerleşim kalıntılarıyla bilinen önemli tarihî alandır.','https://mardin.ktb.gov.tr/Eklenti/6688,mardingezilecekyerlerlistesipdf.pdf?0='),
('Sümela Manastırı','Tarih ve mimari','Trabzon','Altındere Vadisi, Maçka',40.690,39.658,'trabzon-sumela-manastiri','Altındere Vadisi’nde sarp kayalığa kurulmuş, Doğu Karadeniz’in en tanınmış tarihî manastırlarından biri.','Sümela Manastırı, Maçka’daki Altındere Vadisi’ne hâkim kayalıkta yer alır. Ziyaret saatleri mevsime göre değişebilir; yol ve erişim durumu için resmî duyurular kontrol edilmelidir.','https://trabzon.ktb.gov.tr/TR-57674/muze-ve-orenyerleri.html'),
('Trabzon Ayasofya Camii','Tarih ve mimari','Trabzon','Fatih Mahallesi, Ortahisar',41.003,39.696,'trabzon-ayasofya-camii','Trabzon’da Bizans, Gürcü ve Selçuklu mimari etkilerini bir araya getiren tarihî yapı.','Trabzon Ayasofya, 13. yüzyıla uzanan mimari geçmişi ve özgün süslemeleriyle kentin önemli kültürel miras yapılarındandır. Ziyaret koşulları güncel olarak doğrulanmalıdır.','https://trabzon.ktb.gov.tr/TR-57754/yapmadan-donme.html')
