WHERE NOT EXISTS (SELECT 1 FROM public.places p WHERE p.slug=s.slug)
AND NOT EXISTS (SELECT 1 FROM public.places p WHERE p.city=s.city AND lower(trim(p.name))=lower(trim(s.name)));
UPDATE public.places SET name='Arslantepe Höyüğü', short_description='UNESCO Dünya Mirası alanı; Malatya yakınında binlerce yıllık yerleşim katmanlarını barındıran arkeolojik höyük.', long_description='Arslantepe Höyüğü, MÖ 5. binyıldan Bizans dönemine uzanan yerleşim katmanlarıyla Anadolu’nun önemli arkeolojik alanlarındandır. Bakanlığın duyurusunda 1 Eylül 2025 itibarıyla geçici ziyaret kapanışı belirtilmiştir; ziyaret öncesinde güncel durumu doğrulayın.', source_url='https://malatya.ktb.gov.tr/TR-58312/arslantepe.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Malatya' AND slug='osm-way-183451728';
